#!/usr/bin/env python3
"""Package source-backed two-pair curriculum, evidence and credits; no publishing."""
import hashlib, json, pathlib, urllib.parse
from datetime import datetime, timezone
from discover import BASE, write
from acquire import source_data

def main():
 selected=source_data()
 entries={word:entry for _,word,_,entry,_,_ in selected}
 pairs=[]
 for short,long,meaning_short,meaning_long,coda in [('in','ihn','in','him; direct object','n'),('im','ihm','in the','to him; dative','m')]:
  source_urls=['https://de.wiktionary.org/w/index.php?'+urllib.parse.urlencode({'title':w,'oldid':entries[w]['revisions'][0]['revid']})for w in[short,long]]
  pairs.append({'id':f'de-{short}-{long}','words':[{'text':short,'ipa':'/ɪ'+coda+'/','meaning':meaning_short,'phonemes':['ɪ',coda]},{'text':long,'ipa':'/iː'+coda+'/','meaning':meaning_long,'phonemes':['iː',coda]}],'kind':'minimal','sources':source_urls,'validation':{'text':'primary-dictionary-citation-forms-source-checked','audio':'pending-listening-review'},'note':'Compare isolated stressed citation forms. Connected-speech reduction and actual glottal onset realization are outside this target; audio still requires listening.','abx':{'categoryByWordIndex':[0,1],'targetTokenIndex':0,'targetPosition':'initial','trialGroup':'all'}})
 contrast={'id':'de-i-length-pronouns','label':'In or ihn?','phonemes':['ɪ','iː'],'description':'Compare the short vowel in in and im with the long vowel in ihn and ihm. Vowel quality and duration both matter.','targetSoundFocus':'Listen to the initial vowel. The final consonant changes between pairs.','l1Notes':[],'pairs':pairs,'sources':sorted({url for p in pairs for url in p['sources']}),'abx':{'matchType':'phoneme','targetSoundFocus':'Listen to the initial vowel.','prompt':'Which reference shares X’s target sound?','categoryLabels':['ɪ','iː'],'categoryOrder':'words[0] is category 0; words[1] is category 1','xMustUseDifferentPair':True,'xMustExcludeBothReferenceWordTexts':True,'presentation':'audio-only-until-answer-or-explicit-text-assist'}}
 candidate={'schemaVersion':1,'status':'isolated-source-backed-candidate-unreviewed','sourceCollectionId':'human-de-i-length-pronouns-v1','mainCurriculumEdited':False,'pairCount':2,'scopeLimit':'Two pairs only. Small fixed word/token pool permits memorization; this is not a learning-efficacy or held-out-transfer test.','languages':[{'id':'de','name':'German','nativeName':'Deutsch','locale':'de-DE','dialect':'Standard German citation-form targets; actual speaker accents unreviewed','tagline':'Compare two German vowel categories using four short words.','contrasts':[contrast],'scope':'Two-pair optional human-recording candidate, separate from the main curriculum.','audioStatus':'Source and licenses checked; pronunciation and speaker consistency pending listening.'}]}
 write(BASE/'curriculum.candidate.json',candidate)
 source_audit=[]
 for speaker,word,page,entry,transcription,ipa in selected:
  info=page['imageinfo'][0];revision=page['revisions'][0]
  source_audit.append({'word':word,'voiceId':speaker['id'],'creator':speaker['name'],'sourceTitle':page['title'],'sourcePageRevision':revision['revid'],'sourcePageRevisionTimestamp':revision['timestamp'],'sourceSha1':info['sha1'],'sourceBytes':info['size'],'originalUploadTimestamp':info['timestamp'],'license':speaker['licenseId'],'licenseUrl':speaker['licenseUrl'],'exactWordEvidence':transcription,'dictionaryIPA':ipa,'dictionaryRevision':entry['revisions'][0]['revid'],'nativeDialectEvidenceStatus':speaker['dialectSourceStatus'],'phoneticListeningVerified':False})
 current_gaps=[
  {'contrastId':'de-u-ue','completeContributor':'Jeuwre','nearestPartialProfiles':[{'name':'Dinock90','present':['wurde','würde','Mutter'],'missing':['musste','müsste','Mütter']},{'name':'Natschoba','present':['musste','wurde','Mütter'],'missing':['müsste','würde','Mutter']}],'decisiveGap':'No second exact isolated müsste found; phrase recordings do not count. Natschoba die Mutter is not Mutter.','prefixEvidence':'sources/prefix-müsste.json'},
  {'contrastId':'de-i-length','completeContributor':'Jeuwre','nearestPartialProfiles':[{'name':'Sebastian Wallroth','present':['Mitte','Miete','Schiff'],'missing':['bitten','bieten','schief']},{'name':'Natschoba','present':['bitten','schief'],'missing':['bieten','Mitte','Miete','Schiff']}],'decisiveGap':'No second exact isolated bieten found. All three checked historical versions of De-bieten are uploaded by Jeuwre.','prefixEvidence':'sources/prefix-bieten.json'},
  {'contrastId':'de-s-z','completeContributor':'Jeuwre','decisiveGap':'No second exact Muße found in focused audio/prefix search.','prefixEvidence':'sources/prefix-Muße.json'},
  {'contrastId':'de-o-oe','completeContributor':'Jeuwre','decisiveGap':'No second exact Rohre found in focused audio/prefix search. Broad rote search capped at 100 of 114 results; not claimed exhaustive.','prefixEvidence':'sources/prefix-Rohre.json'},
 ]
 alternatives={'acceptedTwoPairs':['in/ihn','im/ihm'],'contributors':['Jeuwre','joni'],'thirdPairMissing':'ihnen/innen: both contributors have ihnen; only Jeuwre innen was located. No numbered De-innen alternate in complete prefix listing.','otherCandidateGaps':{'Lied/litt':'Jeuwre both; Lingua Libre Lied credited to Sebastian Wallroth, litt to Natschoba; not one shared second contributor.','Stil/still':'Jeuwre both; no exact Lingua Libre Stil found. De-Stil uses /ʃt/ while De-Stil2 uses /st/; only /ʃt/ version aligns with still.'},'dictionaryEvidence':['sources/alternate-pair-dictionary-map.json','sources/ihnen-innen-dictionary-map.json'],'preservedMinimumDecision':'Root explicitly authorized a complete two-pair/eight-file optional collection after the three-pair search failed.'}
 write(BASE/'source-audit.json',{'checkedAt':datetime.now(timezone.utc).isoformat(),'selected':source_audit,'currentPairCoverageGaps':current_gaps,'alternatePairDecision':alternatives,'searchLimit':'Focused current-pair searches plus four suggested alternate pairs and one targeted third-pair candidate. Absence is limited to checked sources, not all possible recordings.','mainCurriculumEdited':False})
 manifest=json.loads((BASE/'manifest.preview.json').read_text());credits=json.loads((BASE/'attribution.json').read_text())
 timeline=[{'voiceId':c['voiceId'],'text':c['text'],'targetCategory':0 if c['text']in{'in','im'}else 1,'sourceRecordingDate':c['originalRecordingDate'],'currentVersionUploaded':c['originalUploadTimestamp'],'sourceDurationSeconds':c['sourceDurationSeconds'],'sourceSampleRate':c['originalSampleRate'],'sourceChannels':c['originalChannels']}for c in manifest['clips']]
 write(BASE/'recording-conditions-audit.json',{'status':'metadata-only; audible cues unreviewed','records':timeline,'materialLimitation':'Source/upload versions correlate with vowel category within both contributors. Date labels are not proof of different actual recording sessions or audible artifacts. They prevent a controlled-same-session claim.','speakerIdentityVerified':False,'phoneticListeningVerified':False})
 write(BASE/'integration-inventory.json',{'collectionId':manifest['collectionId'],'pairCount':2,'files':[{'path':'clips/'+pathlib.Path(c['url']).name,'url':c['url'],'text':c['text'],'voiceId':c['voiceId'],'sha256':c['sha256'],'bytes':c['bytes'],'license':c['license']['id']}for c in manifest['clips']],'requiredMetadata':['manifest.preview.json','curriculum.candidate.json','attribution.json','ATTRIBUTION.md'],'excluded':['private/','manifest.candidate.json','acquisition-progress.json','sources/'],'publicDeploymentApproved':False,'defaultReplacementApproved':False})
 write(BASE/'listening-review.template.json',{'status':'not-reviewed','instructions':'Listen to every whole file. Source labels, dictionary IPA and successful decoding are not pronunciation approval. Review exact word, category contrast, speaker identity, artifacts and naturalness separately.','clips':[{'text':c['text'],'voiceId':c['voiceId'],'targetIPA':c['targetIPA'],'localPath':'clips/'+pathlib.Path(c['url']).name,'sha256':c['sha256'],'exactWord':None,'targetVowel':None,'glottalOnsetAndCodaMatchPair':None,'speakerIdentityConsistent':None,'clippingOrExtraSpeech':None,'categoryLinkedRecordingArtifacts':None,'naturalness':None,'notes':''}for c in manifest['clips']],'pairChecks':[{'pairId':p['id'],'voiceId':s['id'],'onlyTargetContrastDiffers':None,'notes':''}for p in pairs for s in SPEAKER_PUBLIC(manifest)],'approvedForAssessment':False})
 lines=['# German human audio credits','', 'Exactly eight recordings for the two-pair in/ihn and im/ihm candidate. Pronunciation and speaker consistency are unreviewed. Each encoded file retains the license version shown below; there is no blanket relicensing of the collection.','']
 for c in credits['records']:
  lines.extend([f"- **{c['text']} — {c['author']}**. [{c['title']}]({c['sourcePage']}); [audited page revision]({c['sourceRevision']}); [{c['license']}]({c['licenseUrl']}). {c['changes']}"])
  for key in['copyrightNotice','additionalAttribution','originalLicenseNotice']:
   if c[key]:lines.append(f"  Retained {key}: {c[key]}")
 lines.extend(['','These credits identify source contributors and do not imply endorsement. The derivative MP3s retain their per-file ShareAlike license. No DRM or additional license restrictions should be applied to these assets.'])
 (BASE/'ATTRIBUTION.md').write_text('\n'.join(lines)+'\n')
 evidence=[{'path':str(path.relative_to(BASE)),'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'bytes':path.stat().st_size}for path in sorted((BASE/'sources').glob('*.json'))]
 write(BASE/'source-evidence-index.json',{'retainedAt':datetime.now(timezone.utc).isoformat(),'files':evidence,'note':'Primary API responses and derived search maps; originals kept separately. No listening claim.'})
 print(json.dumps({'pairs':2,'clips':len(manifest['clips']),'sourceRecords':len(source_audit),'evidenceFiles':len(evidence),'mainCurriculumEdited':False}))
def SPEAKER_PUBLIC(manifest):return manifest['voicesByLanguage']['de']
if __name__=='__main__':main()
